const context = $('Build thread context').first().json;
const raw = String($input.first().json.output || $input.first().json.text || '{}').replace(/^\s*\x60\x60\x60(?:json)?\s*|\s*\x60\x60\x60\s*$/gi, '');
let ai = {};
try { ai = JSON.parse(raw); } catch { ai = { decision: 'manual_required', decision_reason: 'AI ni vrnil veljavnega strukturiranega JSON-a.', confidence: 0, category: 'manual_review', category_confidence: 0 }; }
return [{ json: { ...context, ...ai, auto_reply_count: context.auto_reply_count } }];

// n8n Code node: postavite ga takoj za "Analyze Email + Decision Engine".
// Node ne pošilja e-pošte; samo uveljavi strožja pravila nad AI outputom.
const manualPatterns = [
  /reklamac|prito(?:z|ž)b|nezadovoljn/iu,
  /vlom|varnostn(?:i|ega)? incident|napad|gro(?:z|ž)nj/iu,
  /nujn(?:a|o|e)? intervenc|napak(?:a|e)?.{0,30}(?:alarm|vnc)|(?:alarm|vnc).{0,30}napak/iu,
  /pogodb|odpoved|odvet|to(?:z|ž)b|pravn/iu,
];
const reviewPatterns = [
  /cen|cena|cenik|popust|predra(?:c|č)un|ponudb/iu,
  /rok izvedbe|rok monta(?:z|ž)e|termin izvedbe|kdaj.{0,30}(?:izvedete|montirate)/iu,
  /tehni(?:c|č)n.{0,30}re(?:s|š)itev|koliko varnostnikov/iu,
];
const unsafeDraftPatterns = [
  /€|eur|evr|cena (?:je|bo)|popust (?:je|bo|odobren)/iu,
  /(?:potrjujemo|zagotavljamo|obljubljamo).{0,45}(?:termin|rok|izvedbo|ceno|popust)/iu,
  /(?:izvedli|montirali|pri(?:s|š)li) bomo.{0,35}(?:do|dne|ob|v roku)/iu,
  /(?:potrebujete|dolo(?:c|č)ili smo).{0,25}(?:varnostnikov|konkretno re(?:s|š)itev|sistem)/iu,
];
const safeMissingPatterns = [
  /naslov|lokacij/iu,
  /velikost|povr(?:s|š)in|kvadratur/iu,
  /kontaktna oseba|ime in priimek|kontakt/iu,
  /telefon|mobiln/iu,
  /tip objekta|vrsta objekta|namembnost/iu,
  /opis potrebe|opis objekta|kaj potrebujete/iu,
  /tip storitve|vrsta storitve|(?:z|ž)elena storitev/iu,
];
const validCategories = new Set(['order', 'installation', 'service']);

function asObject(value) {
  if (value && typeof value === 'object') return value;
  try { return JSON.parse(String(value || '{}').replace(/^```json\s*|\s*```$/g, '')); }
  catch { return {}; }
}

return $input.all().map((item) => {
  const input = item.json;
  const ai = asObject(input.output || input.ai_output || input.analysis || input);
  const missing = Array.isArray(ai.missing_data) ? ai.missing_data.map(String).filter(Boolean) : [];
  const confidence = Math.max(0, Math.min(1, Number(ai.confidence) || 0));
  const requestedCategory = String(ai.category || '').trim().toLowerCase();
  const categoryConfidence = Math.max(0, Math.min(1, Number(ai.category_confidence) || 0));
  const categoryReviewRequired = !validCategories.has(requestedCategory) || categoryConfidence < 0.85;
  const category = categoryReviewRequired ? 'manual_review' : requestedCategory;
  const autoReplyCount = Math.max(0, Math.trunc(Number(input.auto_reply_count ?? ai.auto_reply_count) || 0));
  const content = `${input.subject || ''}\n${input.body || input.text || ''}`;
  const draft = String(ai.draft_reply || '');
  let decision = ['auto_clarification', 'review_required', 'manual_required'].includes(ai.decision) ? ai.decision : 'review_required';
  let reason = String(ai.decision_reason || 'Če obstaja dvom, je potrebna človeška potrditev.');
  let safe = ai.safe_to_auto_send === true;

  if (categoryReviewRequired) {
    decision = 'manual_required';
    safe = false;
    reason = 'Kategorija ni dovolj zanesljiva, zato je sporočilo usmerjeno v Ročni pregled.';
  } else if (manualPatterns.some((pattern) => pattern.test(content)) || confidence < 0.90) {
    decision = 'manual_required';
    safe = false;
    reason = confidence < 0.90 ? 'AI confidence je nižji od 0,90.' : 'Zaznana je reklamacija, incident, nujna ali pravno občutljiva zadeva.';
  } else if (decision === 'auto_clarification') {
    const allMissingSafe = missing.length > 0 && missing.every((entry) => safeMissingPatterns.some((pattern) => pattern.test(entry)));
    const draftSafe = draft && !unsafeDraftPatterns.some((pattern) => pattern.test(draft));
    const contentSafe = !reviewPatterns.some((pattern) => pattern.test(content));
    if (!safe || !allMissingSafe || !draftSafe || !contentSafe || autoReplyCount >= 1) {
      decision = 'review_required';
      safe = false;
      reason = autoReplyCount >= 1 ? 'V threadu je bil samodejni clarification že poslan.' : 'Samodejni odgovor ni prestal vseh determinističnih varnostnih preverjanj.';
    }
  } else {
    safe = false;
  }

  return { json: { ...input, ...ai, category, category_confidence: categoryConfidence, category_review_required: categoryReviewRequired, decision, safe_to_auto_send: decision === 'auto_clarification' && safe, decision_reason: reason, confidence, missing_data: missing, draft_reply: draft, thread_id: String(input.thread_id || ai.thread_id || ''), auto_reply_count: autoReplyCount, status: decision } };
});

const item = $input.first().json;
const text = (value, max = 12000) => String(value ?? '').trim().slice(0, max);
return [{ json: {
  order_id: text(item.order_id, 120), email_type: 'inbound_email', sender_email: text(item.sender_email, 320),
  customer_name: text(item.customer_name, 180), company_name: text(item.company_name, 180), subject: text(item.subject, 300),
  body: text(item.body), summary: text(item.summary, 2500), sku: text(item.sku, 160), description: text(item.description, 800),
  quantity: Number.isFinite(Number(item.quantity)) ? Number(item.quantity) : null, unit: text(item.unit, 80), requested_date: text(item.requested_date, 100),
  priority: text(item.priority, 80) || 'običajna', status: text(item.status, 80), created_at: item.created_at || new Date().toISOString(),
  missing_data: JSON.stringify(Array.isArray(item.missing_data) ? item.missing_data : []), draft_reply: text(item.draft_reply),
  category: text(item.category, 80), category_confidence: Number(item.category_confidence) || 0, category_review_required: item.category_review_required === true,
  decision: text(item.decision, 80), safe_to_auto_send: item.safe_to_auto_send === true, decision_reason: text(item.decision_reason, 2000), confidence: Number(item.confidence) || 0,
  thread_id: text(item.thread_id, 240), gmail_message_id: text(item.gmail_message_id, 240), auto_reply_count: Math.max(0, Math.trunc(Number(item.auto_reply_count) || 0)),
  approved_at: null, sent_at: null, message_id: '', send_error: ''
} }];

const row = $('Insert FIT inbound email').first().json;
const gmail = $input.first().json || {};
return [{ json: { ...row, status: 'sent', sent_at: new Date().toISOString(), message_id: String(gmail.id || gmail.messageId || gmail.message_id || ''), send_error: '', auto_reply_count: Math.max(0, Math.trunc(Number(row.auto_reply_count) || 0)) + 1 } }];
